namespace RockPro{public static class LatchInProcess{
static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=64000000};static IZSceneDoc S;static IZSceneDocUtility U;static Type Controller;static Dictionary<string,object> Manifest;static string Log;static List<object> Checks;
static Dictionary<string,object> O(object x){return (Dictionary<string,object>)x;}static double[] N(object x){return ((Array)x).Cast<object>().Select(Convert.ToDouble).ToArray();}static IZDoc D(object x){return x is IZDoc?(IZDoc)x:(IZDoc)Marshal.GetObjectForIUnknown(new IntPtr(Convert.ToInt64(x)));}
static string Hash(string p){using(var f=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
static void Mark(string x){File.AppendAllText(Log,DateTime.UtcNow.ToString("o")+" "+x+Environment.NewLine);}static double V(string n){return S.ParameterMgr.GetParameterByName(n).Value*1000;}
static double[] M(IZSceneElement e){var m=e.GetTransformToGlobal();return Enumerable.Range(0,16).Select(i=>m.GetValue(i/4,i%4)).ToArray();}
static double[] Center(IZProfile p){return (double[])Controller.GetMethod("ContourCenter").Invoke(null,new object[]{p});}
static IZFeature Feature(IZSceneDocUtility u,int part,int id){var mgr=(IZPartFeatureMgr)u.GetElementById(part);for(int i=0;i<mgr.GetFeaturesCount();i++)if(((IZElement)mgr.GetFeatureAt(i)).Id==id)return mgr.GetFeatureAt(i);throw new Exception("Missing reference feature "+id);}
static double[] Turn(double[] m,double angle,double x,double y){var r=(double[])m.Clone();double c=Math.Cos(angle),s=Math.Sin(angle);for(int i=0;i<3;i++){r[i*4]=m[i*4]*c-m[i*4+1]*s;r[i*4+1]=m[i*4]*s+m[i*4+1]*c;}r[12]=x;r[13]=y;return r;}
static void Picture(string path){var c=(IZCamera)S.CameraMgr.ActiveCamera;c.Perspective=false;c.Direction=new double[]{.65,.85,-.5};c.Up=new double[]{0,0,1};S.AdjustCameraToFitShapeInRect(1500,1100);S.Redraw();S.ExportImage(path,eZImageFormat.Z_IMAGE_PNG,1500,1100,true);}
static void Check(string name){Mark("check "+name);var watch=System.Diagnostics.Stopwatch.StartNew();Controller.GetMethod("Apply").Invoke(null,new object[]{S});watch.Stop();var errors=new List<object>();double gap=0;
 foreach(var row in ((object[])Manifest["rows"]).Select(O)){int n=(int)Math.Round(S.ParameterMgr.GetParameterByName((string)row["count"]).Value);var slots=(object[])row["slots"];double center=V((string)row["center"]),span=V((string)row["spread"]);for(int i=0;i<slots.Length;i++)foreach(object id in (object[])slots[i]){var e=U.GetElementById(Convert.ToInt32(id));if(e.GetStateStatus(eZElementState.Z_SUPPRESSED)!=(i>=n))errors.Add(new{id=id,error="Quantity mismatch"});if(i<n&&e.Type==eZElementType.Z_ELEMENT_ASSEMBLY){double expected=-1011.5+center+(n==1?0:(-0.5+(double)i/(n-1))*span);double actual=M((IZSceneElement)e)[13]*1000;if(Math.Abs(expected-actual)>.08)errors.Add(new{id=id,error="Row position",actual=actual,expected=expected});}}}
 int cuts=0;foreach(var mate in ((object[])Manifest["mates"]).Select(O)){var e=U.GetElementById(Convert.ToInt32(mate["id"]));if(e.GetStateStatus(eZElementState.Z_SUPPRESSED))continue;var root=U.GetElementById(Convert.ToInt32(mate["root"]));if(root.GetStateStatus(eZElementState.Z_SUPPRESSED))continue;cuts++;var m=M((IZSceneElement)root);var offset=N(mate["local"]);var expected=Enumerable.Range(0,3).Select(j=>m[12+j]+Enumerable.Range(0,3).Sum(k=>offset[k]*m[k*4+j])).ToArray();var p=((IZExtrudeFeature)e).CrossSection;var actual=Center(p);double error=Enumerable.Range(0,3).Max(k=>Math.Abs(actual[k]-expected[k])*1000);gap=Math.Max(gap,error);if(error>.08)errors.Add(new{id=mate["id"],error="Cut/mount mismatch",mm=error});var lengths=((Array)p.GetCurveIds()).Cast<object>().Select(x=>p.GetCurveLength(Convert.ToInt32(x))).OrderBy(x=>x).ToArray();var old=N(mate["lengths"]);if(lengths.Length!=old.Length||lengths.Zip(old,(a,b)=>Math.Abs(a-b)*1000).Max()>.01)errors.Add(new{id=mate["id"],error="Contour changed"});}
 var check=new{name=name,passed=errors.Count==0,active_cuts=cuts,max_cut_mount_error_mm=gap,apply_ms=watch.Elapsed.TotalMilliseconds,errors=errors};Checks.Add(check);if(errors.Count>0)throw new Exception("Failed "+name);
}
public static int Run(string folder){var result=new Dictionary<string,object>();IZDoc owned=null,reference=null;bool pass=false;Checks=new List<object>();Log=Path.Combine(folder,"progress.txt");try{
 var q=O(J.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json"))));if((string)q["contract"]!="rockpro-tv-quantity-complete-v2"||System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Wrong request/host");
 dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)legacy.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");var before=((Array)app.GetAllOpenDocs()).Cast<object>().Select(D).Select(d=>new{path=d.Name,modified=d.Modified}).ToArray();
 string source=(string)q["source"],original=(string)q["original"],output=(string)q["output"];if(Hash(source)!=(string)q["sha256"]||Hash(original)!=(string)q["original_sha256"]||File.Exists(output))throw new Exception("Source changed/output exists");
 foreach(var a in AppDomain.CurrentDomain.GetAssemblies()){var type=a.GetType("RockPro.CAD.MountCountController");if(type!=null)type.GetMethod("Stop").Invoke(null,null);}
 Controller=Assembly.LoadFrom((string)q["controller"]).GetType("RockPro.CAD.MountCountController");if(Hash(Controller.Assembly.Location)!=Hash((string)q["controller"]))throw new Exception("Cached controller mismatch");Controller.GetField("Suspended").SetValue(null,true);Mark("controller "+Controller.Assembly.FullName);
 string refPath=Path.Combine(folder,"reference.ics");File.Copy(original,refPath,false);bool already;reference=app.OpenFile2(refPath,false,true,out already);if(already){reference=null;throw new Exception("Reference already open");}var originalScene=(IZSceneDoc)reference;var originalU=(IZSceneDocUtility)reference;
 var golden=new Dictionary<int,double[]>();var centers=new Dictionary<int,double[]>();var lengthsBy=new Dictionary<int,double[]>();var oldHeights=new Dictionary<string,double>();
 var specs=((object[])q["rows"]).Select(O).ToArray();foreach(var r in specs){var halves=(string)r["kind"]=="handle"?new[]{r}:((object[])r["halves"]).Select(O).ToArray();foreach(var h in halves){int root=Convert.ToInt32(h["source_mount"]);golden[root]=M((IZSceneElement)originalU.GetElementById(root));if((string)r["kind"]=="handle")oldHeights[(string)r["height"]]=originalScene.ParameterMgr.GetParameterByName((string)r["height"]).Value*1000;foreach(var cut in ((object[])h["cuts"]).Select(O)){int id=Convert.ToInt32(cut["source_feature"]);var p=((IZExtrudeFeature)Feature(originalU,Convert.ToInt32(cut["source_part"]),id)).CrossSection;centers[id]=Center(p);lengthsBy[id]=((Array)p.GetCurveIds()).Cast<object>().Select(x=>p.GetCurveLength(Convert.ToInt32(x))).OrderBy(x=>x).ToArray();}}}reference.Close2(true);reference=null;Mark("reference mounting contours captured");
 string working=Path.Combine(folder,"working.ics");File.Copy(source,working,false);owned=app.OpenFile2(working,false,true,out already);if(already){owned=null;throw new Exception("Working copy already open");}S=(IZSceneDoc)owned;U=(IZSceneDocUtility)S;S.ConstraintSolver=false;
 var props=S.GetTopElement().get_CustomPropMgr(false);Manifest=O(J.DeserializeObject((string)props.GetValueByName("RockPro.MountCounts.v1")));var manifestRows=((object[])Manifest["rows"]).Select(O).ToArray();var poses=new List<object>();var mates=new List<object>();
 for(int ri=0;ri<specs.Length;ri++){var r=specs[ri];var row=manifestRows[ri];if((string)row["count"]!=(string)r["count"])throw new Exception("Row mapping differs");var slots=(object[])row["slots"];for(int i=0;i<slots.Length;i++){var ids=(object[])slots[i];int cursor=0;var halves=(string)r["kind"]=="handle"?new[]{r}:((object[])r["halves"]).Select(O).ToArray();foreach(var h in halves){int root=Convert.ToInt32(ids[cursor++]),sourceRoot=Convert.ToInt32(h["source_mount"]);var old=golden[sourceRoot];string section=(string)h["section"];var frame=(double[])old.Clone();bool handle=(string)r["kind"]=="handle",right=(string)r["side"]=="Prawa";
 if(!handle)frame=Turn(old,right?Math.PI/2:-Math.PI/2,right?(-2032+V("RP_SzerokoscSkrzyni"))/1000:-2.032,(-1011.5+V((string)r["center"]))/1000);
 poses.Add(new{id=root,world=frame,index=i,count=r["count"],center=r["center"],spread=r["spread"],right=right,height=handle?(string)r["height"]:"",height_base=handle?oldHeights[(string)r["height"]]:0,follow_body=!handle||section=="Czapka",cap=section=="Czapka"});
 foreach(var cut in ((object[])h["cuts"]).Select(O)){int id=Convert.ToInt32(ids[cursor++]),sourceCut=Convert.ToInt32(cut["source_feature"]);var c=centers[sourceCut];var local=Enumerable.Range(0,3).Select(a=>Enumerable.Range(0,3).Sum(k=>(c[k]-old[12+k])*old[a*4+k])).ToArray();mates.Add(new{id=id,root=root,local=local,lengths=lengthsBy[sourceCut]});}
 }} }
 Manifest["contract"]="rockpro-tv-counts-v2";Manifest["poses"]=poses.ToArray();Manifest["mates"]=mates.ToArray();Manifest["base_width"]=V("RP_SzerokoscSkrzyni");Manifest["base_body"]=V("RP_WysokoscDolu");Manifest["base_lift"]=V("RP_UniesienieCzapki");Manifest=O(J.DeserializeObject(J.Serialize(Manifest)));props.SetValueByName("RockPro.MountCounts.v1",J.Serialize(Manifest));
 var defaults=Enumerable.Range(0,S.ParameterMgr.Count).Select(i=>S.ParameterMgr.GetParameter(i)).Where(p=>p.Type!=eZParamType.Z_PARAMETER_TYPE_TEXT).ToDictionary(p=>p.Name,p=>p.Expression);Action restore=()=>{foreach(var p in defaults)S.ParameterMgr.GetParameterByName(p.Key).Expression=p.Value;};
 Check("po_dwa");Picture(Path.Combine(folder,"po_dwa.png"));foreach(var row in manifestRows)S.ParameterMgr.GetParameterByName((string)row["count"]).Expression=Convert.ToInt32(row["minimum"])==0?"0":"1";Check("jeden_uchwyt_zero_zamkow");Picture(Path.Combine(folder,"po_jednym.png"));
 restore();S.ParameterMgr.GetParameterByName("RP_GlebokoscSkrzyni").Expression="972 mm";S.ParameterMgr.GetParameterByName("RP_WysokoscDolu").Expression="528.99 mm";foreach(var row in manifestRows)S.ParameterMgr.GetParameterByName((string)row["count"]).Expression=((string)row["count"]).Contains("Lewa")?"3":"1";Check("trzy_i_jeden_zmiana_gabarytow");Picture(Path.Combine(folder,"trzy_i_jeden.png"));
 restore();S.ParameterMgr.GetParameterByName("RP_GlebokoscSkrzyni").Expression="972 mm";foreach(var row in manifestRows)S.ParameterMgr.GetParameterByName((string)row["count"]).Expression="4";Check("cztery");restore();Check("powrot");S.SaveAs(output,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);owned.Close2(true);owned=null;
 owned=app.OpenFile2(output,false,true,out already);if(already){owned=null;throw new Exception("Output already open");}S=(IZSceneDoc)owned;U=(IZSceneDocUtility)S;Check("ponowne_otwarcie");foreach(var row in manifestRows)S.ParameterMgr.GetParameterByName((string)row["count"]).Expression="3";Check("edycja_po_otwarciu");restore();Check("finalny_powrot");Picture(Path.Combine(folder,"final.png"));S.SaveAs(output,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);
 foreach(var old in before){var d=((Array)app.GetAllOpenDocs()).Cast<object>().Select(D).Single(x=>x.Name==old.path);if(d.Modified!=old.modified)throw new Exception("Existing document changed "+old.path);}if(Hash(source)!=(string)q["sha256"]||Hash(original)!=(string)q["original_sha256"])throw new Exception("Reference changed");
 Controller.GetMethod("Start").Invoke(null,new object[]{app});Controller.GetField("Suspended").SetValue(null,false);app.ActiveDoc=owned;result["output"]=output;result["output_sha256"]=Hash(output);result["manifest"]=Manifest;result["sources_unchanged"]=true;result["existing_documents_preserved"]=true;pass=true;
}catch(Exception ex){result["error"]=ex.ToString();if(owned!=null)try{S.SaveAs(Path.Combine(folder,"FAILED_DO_NOT_USE.ics"),eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);owned.Close2(true);}catch(Exception e){result["cleanup_error"]=e.ToString();}}finally{if(reference!=null)reference.Close2(true);}result["checks"]=Checks;result["passed"]=pass;File.WriteAllText(Path.Combine(folder,"result.json"),J.Serialize(result));return pass?0:1;}}}
